import sys
from collections import deque

def max_flow_with_increase(n, k, capacity):
    def bfs(source, sink, parent):
        visited = [False] * n
        queue = deque([source])
        visited[source] = True
        while queue:
            u = queue.popleft()
            for v in range(n):
                if not visited[v] and capacity[u][v] > 0:
                    queue.append(v)
                    visited[v] = True
                    parent[v] = u
                    if v == sink:
                        return True
        return False

    def dfs(u, flow, sink, parent):
        if u == sink:
            return flow
        min_flow = float('inf')
        for v in range(n):
            if capacity[u][v] > 0 and parent[v] == -1:
                parent[v] = u
                min_flow = min(min_flow, dfs(v, min(flow, capacity[u][v]), sink, parent))
                if min_flow > 0:
                    capacity[u][v] -= min_flow
                    capacity[v][u] += min_flow
                    return min_flow
        parent[u] = -1
        return 0

    def ford_fulkerson(source, sink):
        parent = [-1] * n
        max_flow = 0
        while bfs(source, sink, parent):
            path_flow = dfs(source, float('inf'), sink, parent)
            max_flow += path_flow
        return max_flow

    original_max_flow = ford_fulkerson(0, n-1)

    # Try to increase capacities
    for u in range(n):
        for v in range(n):
            if capacity[u][v] > original_max_flow:
                continue
            increase = min(k, capacity[u][v] - capacity[u][v] % original_max_flow)
            if increase == 0:
                continue
            capacity[u][v] += increase
            k -= increase
            new_max_flow = ford_fulkerson(0, n-1)
            if new_max_flow > original_max_flow:
                original_max_flow = new_max_flow
            capacity[u][v] -= increase
            k += increase

    return original_max_flow

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    k = int(input[1])
    capacity = [[int(input[n * i + j + 2]) for j in range(n)] for i in range(n)]
    print(max_flow_with_increase(n, k, capacity))

if __name__ == "__main__":
    main()
